import org.eclipse.core.runtime.IProgressMonitor;
import org.eclipse.core.runtime.IStatus;
import org.eclipse.core.runtime.Status;
import org.eclipse.ui.progress.UIJob;

public class TestClass {
    public static class Messages {
        public static String QuickSearchDialog_RefreshJob = "Refresh";
    }

    private void refreshWidgets() {
        System.out.println("Refreshing widgets...");
    }

    private UIJob refreshJob = new UIJob(Messages.QuickSearchDialog_RefreshJob) {
        @Override
        public IStatus runInUIThread(IProgressMonitor monitor) {
            refreshWidgets();
            return Status.OK_STATUS;
        }
    };

    public void startJob() {
        refreshJob.schedule();
    }
}

afterExample:
import org.eclipse.core.runtime.ICoreRunnable;
import org.eclipse.core.runtime.IProgressMonitor;
import org.eclipse.core.runtime.IStatus;
import org.eclipse.core.runtime.Status;
import org.eclipse.ui.progress.UIJob;

public class TestClass {
    public static class Messages {
        public static String QuickSearchDialog_RefreshJob = "Refresh";
    }

    private void refreshWidgets() {
        System.out.println("Refreshing widgets...");
    }

    private UIJob refreshJob = UIJob.create(Messages.QuickSearchDialog_RefreshJob,
            (ICoreRunnable) monitor -> refreshWidgets());

    public void startJob() {
        refreshJob.schedule();
    }
}

