import org.eclipse.core.runtime.IProgressMonitor;
import org.eclipse.core.runtime.IStatus;
import org.eclipse.core.runtime.Status;
import org.eclipse.ui.progress.UIJob;
import org.eclipse.core.jobs.Job;

public class NegativeTestClass {
    public static class Messages {
        public static String QuickSearchDialog_OtherJob = "Other Job";
    }

    private void performOtherTask() {
        System.out.println("Performing other task...");
    }

    // This job's runInUIThread has conditional logic and different return paths,
    // so it should not match the proposed rule which assumes a single body and OK_STATUS return.
    private UIJob complexJob = new UIJob(Messages.QuickSearchDialog_OtherJob) {
        @Override
        public IStatus runInUIThread(IProgressMonitor monitor) {
            if (monitor.isCanceled()) {
                return Status.CANCEL_STATUS;
            }
            performOtherTask();
            return Status.OK_STATUS;
        }
    };

    // A non-UIJob should not match
    private Job backgroundJob = new Job("Background Task") {
        @Override
        protected IStatus run(IProgressMonitor monitor) {
            return Status.OK_STATUS;
        }
    };
}
